import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] t = new int[n + 1];
        for (int i = 1; i <= n; i++) t[i] = nextInt();
        long answer = 0;
        for (int i = 1; i <= n; i++) {
            // Request i breaks a limit when the request `limit` places earlier is still in the window.
            if ((i > 3 && t[i] == t[i - 3]) || (i > 20 && t[i] - t[i - 20] < 10) || (i > 60 && t[i] - t[i - 60] < 60)) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n := readInt()
	t := make([]int, n+1)
	for i := 1; i <= n; i++ {
		t[i] = readInt()
	}
	answer := 0
	for i := 1; i <= n; i++ {
		// Request i breaks a limit when the request `limit` places earlier is still in the window.
		if (i > 3 && t[i] == t[i-3]) || (i > 20 && t[i]-t[i-20] < 10) || (i > 60 && t[i]-t[i-60] < 60) {
			answer++
		}
	}
	fmt.Println(answer)
}
